    base_csv[i, "dep_delay_category"] &lt;- NA
  } else if (base_csv$dep_delay[[i]] &lt;= -30) {
    base_csv[i, "dep_delay_category"] &lt;- delay_categories[[1]]
  } else if (base_csv$dep_delay[[i]] &lt;= 30) {
    base_csv[i, "dep_delay_category"] &lt;- delay_categories[[2]]
  } else {
    base_csv[i, "dep_delay_category"] &lt;- delay_categories[[3]]
  }
}
